package com.powercms.cms.widget.web;
import com.powercms.cms.widget.WidgetService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/sites/{siteId}/widgets") class WidgetController { private final WidgetService service; WidgetController(WidgetService s){service=s;} record Save(String code,String name,String controllerDefinition,String parameterSchema){} @GetMapping @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'read')") List<WidgetService.Info> list(@PathVariable UUID siteId){return service.list(siteId);} @PostMapping @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'write')") WidgetService.Info save(@PathVariable UUID siteId,@RequestBody Save r,Authentication a){return service.save(siteId,null,r.code(),r.name(),r.controllerDefinition(),r.parameterSchema(),a.getName());} @PostMapping("/{id}/publish") @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'publish')") WidgetService.Info publish(@PathVariable UUID siteId,@PathVariable UUID id,Authentication a){return service.publish(siteId,id,a.getName());} @DeleteMapping("/{id}") @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'write')") void delete(@PathVariable UUID siteId,@PathVariable UUID id,Authentication a){service.delete(siteId,id,a.getName());} }
